// Rewrites src/lib/version.ts from the repo root Cargo.toml so the landing
// version can never drift from the crate (single source of truth).
// Wired as predev/prebuild; commit the regenerated file with version bumps.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const manifest = readFileSync(new URL("../../Cargo.toml", import.meta.url), "utf8");
const version = /^version\s*=\s*"([^"]+)"/m.exec(manifest)?.[1];

if (!version) {
  console.error("sync-version: could not parse `version` from ../Cargo.toml");
  process.exit(1);
}

const target = fileURLToPath(new URL("../src/lib/version.ts", import.meta.url));
writeFileSync(
  target,
  `// AUTO-GENERATED by \`scripts/sync-version.mjs\` from ../Cargo.toml.\n` +
    `// Do not edit by hand — run \`pnpm sync-version\` after bumping the crate version.\n` +
    `export const PAKMAP_VERSION = "${version}";\n`,
);

console.log(`sync-version: PAKMAP_VERSION = ${version}`);
